    // ---------- canonical preview environments ----------
    async savePreviewEnvironment(input: {
        id: string;
        organizationId?: string | null;
        projectId?: string | null;
        workspaceId?: string | null;
        runId: string;
        url: string;
        status: string;
    }): Promise<void> {
        return this.db.transaction(async () => {
            const now = Date.now();
            (await (async () => (await this.db
                .prepare(`INSERT INTO preview_environments (id, organization_id, project_id, workspace_id, run_id, url, status, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
           ON CONFLICT(id) DO UPDATE SET url=excluded.url, status=excluded.status, updated_at=excluded.updated_at`)
                .run(input.id, input.organizationId ?? null, input.projectId ?? null, input.workspaceId ?? null, input.runId, input.url, input.status, now, now)))());
        });
    }
    /** The preview record owned by THIS run/workspace — never another run's URL. */
    async previewEnvironmentFor(runId: string, workspaceId?: string | null): Promise<any | null> {
        return this.db.transaction(async () => {
            return (await (async () => {
                const row: any = workspaceId
                    ? (await this.db.prepare(`SELECT * FROM preview_environments WHERE run_id = ? AND workspace_id = ? ORDER BY updated_at DESC LIMIT 1`).get(runId, workspaceId)) : (await this.db.prepare(`SELECT * FROM preview_environments WHERE run_id = ? ORDER BY updated_at DESC LIMIT 1`).get(runId));
                if (!row)
                    return null;
                return {
                    id: String(row.id), organizationId: row.organization_id, projectId: row.project_id,
                    workspaceId: row.workspace_id, runId: String(row.run_id), url: String(row.url),
                    status: String(row.status), createdAt: Number(row.created_at), updatedAt: Number(row.updated_at),
                };
            })()) ?? null;
        });
    }
    async setPreviewEnvironmentStatus(id: string, status: string): Promise<void> {
        return this.db.transaction(async () => {
            (await (async () => (await this.db.prepare(`UPDATE preview_environments SET status = ?, updated_at = ? WHERE id = ?`).run(status, Date.now(), id)))());
        });
    }
